    colors = {v for row in grid for v in row}

    # Find the grid-line color: it forms both nearly solid rows and columns.
    line_color = None
    best = -1
    for color in colors:
        row_score = max((sum(v == color for v in row) for row in grid), default=0)
        col_score = max((sum(grid[r][c] == color for r in range(h)) for c in range(w)), default=0)
        score = row_score + col_score
        if row_score >= w * 0.8 and col_score >= h * 0.8 and score > best:
            line_color, best = color, score

    # Identify the lattice lines, merging adjacent cells in a thick line.
    row_groups = []
    for r in range(h):
        if sum(v == line_color for v in grid[r]) >= w * 0.8:
            if not row_groups or r != row_groups[-1][-1] + 1:
                row_groups.append([r])
